class TokenCache:
    def __init__(self, refresh, clock, skew=30):
        self.refresh = refresh
        self.clock = clock
        self.skew = skew
        self.token = None
        self.expires_at = 0
        self._task = None

    def _valid(self):
        return self.token is not None and self.expires_at > self.clock() + self.skew

    async def _run_refresh(self):
        token, expires_at = await self.refresh()
        self.token, self.expires_at = token, expires_at
        return token

    def _on_done(self, task):
        if self._task is task:
            self._task = None
        # Mark the exception retrieved so an unawaited failure does not warn.
        if not task.cancelled():
            task.exception()

    async def get(self):
        if self._valid():
            return self.token
        task = self._task
        if task is None:
            # The refresh runs in its own task so that cancelling any caller,
            # including the one that started it, never cancels the refresh.
            task = asyncio.ensure_future(self._run_refresh())
            self._task = task
            task.add_done_callback(self._on_done)
        return await asyncio.shield(task)
